from .money import _MAX_CENTS, _cents_to_decimal, _to_cents, format_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    total_cents = 0
    count = 0
    for item in list(amounts):
        total_cents += _to_cents(item)
        count += 1
    if total_cents > _MAX_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(_cents_to_decimal(total_cents)), "count": count}

