import re
from decimal import Decimal

_MAX_CENTS = 100_000_000  # 1000000.00
_STRING_AMOUNT = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _to_cents(value):
    """Validate an amount and return it as an exact integer count of cents.

    Works on the exact digit/exponent representation, so it never performs
    arithmetic under the caller's decimal context and never rounds.
    """
    if isinstance(value, bool):
        raise ValueError("bool is not an amount")
    if isinstance(value, str):
        if not _STRING_AMOUNT.fullmatch(value):
            raise ValueError(f"invalid amount string: {value!r}")
        value = Decimal(value)
    elif isinstance(value, int):
        value = Decimal(int(value))
    elif not isinstance(value, Decimal):
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exp = value.as_tuple()
    if not any(digits):
        raise ValueError("amount must be nonzero")
    if sign:
        raise ValueError("amount must be positive")
    # adjusted() is exact; any value with adjusted exponent >= 7 is >= 10**7.
    if value.adjusted() > 6:
        raise ValueError("amount exceeds 1000000.00")

    # Strip trailing zeros from the fractional part so that a value such as
    # 1.000 is accepted, while a nonzero digit beyond the cent is detected.
    digits = list(digits)
    while exp < 0 and digits[-1] == 0:
        digits.pop()
        exp += 1
    if exp < -2:
        raise ValueError("amount is not exactly representable in cents")

    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    cents = coefficient * 10 ** (exp + 2)
    if cents > _MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def _cents_to_decimal(cents):
    # Built from a string, so the result is exact with exponent -2 regardless
    # of the active decimal context.
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return _cents_to_decimal(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
